-- ====================================================================
-- Magyar Közpolitikai Plakátkorpusz (2025–2026) Adatbázis
-- Készítő: Varga Balázs | Bibó István Szakkollégium
-- Kurzus: Mesterséges intelligencia a társadalom- és politikatudományi kutatásban
-- ====================================================================

DROP TABLE IF EXISTS plakatok;

CREATE TABLE plakatok (
    id VARCHAR(32) PRIMARY KEY,
    datum DATE NOT NULL,
    politikai_tabor VARCHAR(64) NOT NULL,
    kibocsato_tipus VARCHAR(32) NOT NULL,
    hivatalos_kiado VARCHAR(128) NOT NULL,
    fajl_nev VARCHAR(128) NOT NULL,
    plakat_szlogen TEXT NOT NULL,
    vizualis_leiras TEXT NOT NULL,
    formatum_meret VARCHAR(64) NOT NULL,
    politikai_elemzes TEXT NOT NULL,
    forras_nev VARCHAR(128) NOT NULL,
    forras_url TEXT NOT NULL,
    kampany_tonus VARCHAR(32) NOT NULL,
    tartalmi_fokusz TEXT NOT NULL,
    vizualis_szemiotika TEXT NOT NULL,
    szlogen_retorika TEXT NOT NULL,
    latens_tema_id INT NOT NULL,
    latens_tema_nev VARCHAR(128) NOT NULL
);

INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2025_001', '2025-04-06', 'FIDESZ-TÁBOR', 'STATE', 'Magyarország Kormánya (Miniszterelnöki Kabinetiroda)', 'vagott_kepek/HUN_PLAKAT_2025_001.jpg', '„VOKS 2025 – Ne hagyjuk, hogy a fejünk felett döntsenek!”', 'Szigorúan néző Volodimir Zelenszkij, mosolygó Ursula von der Leyen és nevető Manfred Weber portréja kék kormányzati háttér előtt.', 'Óriásplakát / Eurobillboard (504 x 238 cm, 12 m2)', 'Ukrajna EU-csatlakozását közvetlen biztonsági és gazdasági fenyegetésként keretező kormányzati kampány.', '444.hu', 'https://444.hu/2025/04/06/itt-az-uj-plakatkampany-zelenszkij-szigoruan-nez-von-der-leyen-onelegulten-mosolyog-weber-pedig-ordogien-nevet', 'NEGATIV_TAMADO', 'Kormányzati szuverenitásvédelem; a döntéshozatal kiszervezése elleni mozgósítás; Brüsszel és Ukrajna külső nyomásának elutasítása.', 'Tekintélykék kormányzati háttér; montázs technika; V. Zelenszkij és M. Weber szigorú, komor fekete-fehér/szürkített tekintete; aránytalanul nagy arcok.', 'Felszólító tagadás és kollektív cselekvésre buzdítás („Ne hagyjuk, hogy a fejünk felett döntsenek!”); polarizáló, veszélyelhárító keretezés.', 2, 'Állami szuverenitási & háborús diskurzus');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2025_002', '2025-07-01', 'FIDESZ-TÁBOR', 'STATE', 'Magyarország Kormánya (Miniszterelnöki Kabinetiroda)', 'vagott_kepek/HUN_PLAKAT_2025_002.jpg', '„Megmutattuk, hogy van véleményünk! 2 millió nem Ukrajna EU-tagságára!”', 'Tömegjelenetet ábrázoló háttér előtt nagy fehér és nemzeti színű tipográfiával szedett kormányzati üzenet.', 'Óriásplakát / Eurobillboard (504 x 238 cm, 12 m2)', 'A véleménynyilvánító szavazás eredményét hirdető állami kampány, amely társadalmi többséget demonstrált.', 'HVG', 'https://hvg.hu/itthon/20250701_Uj-ukranellenes-plakatokkal-jelentkezett-a-kormany', 'NEGATIV_TAMADO', 'Plebiszciter legitimáció és Ukrajna EU-csatlakozásának elutasítása; véleménynyilvánítás demonstrálása.', 'Tömegjelenet és sárga-kék EU-Ukrajna szimbolika; dinamikus feliratok; számszerűsített többségi legitimáció (2 millió).', 'Győzelmi deklaráció és határozott elutasítás („Megmutattuk, hogy van véleményünk! 2 millió nem Ukrajna EU-tagságára!”); többségi felhatalmazás.', 2, 'Állami szuverenitási & háborús diskurzus');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2025_003', '2025-07-02', 'FIDESZ-TÁBOR', 'PROXY', 'Nemzeti Ellenállás Mozgalom (Apáti Bence)', 'vagott_kepek/HUN_PLAKAT_2025_003.jpg', '„MINT KÉT TOJÁS”', 'Két tojáshéjban ülő, ukrán zászlót lengető Volodimir Zelenszkij és Magyar Péter montázsa.', 'Óriásplakát / Eurobillboard (504 x 238 cm, 12 m2)', 'Az Apáti Bence-féle mozgalom plakátja vizuálisan mosta össze Magyar Pétert Zelenszkijjel.', '444.hu', 'https://444.hu/2025/07/02/dedokampanyban-mossa-ossze-az-apati-fele-mozgalom-zelenszkijt-es-magyar-petert', 'NEGATIV_TAMADO', 'Proxy karaktergyilkosság; Magyar Péter (Tisza) és Volodimir Zelenszkij azonosítása; külföldi érdekek kiszolgálásának vádja.', 'Gúnyos karikatúra és szürreális montázs; törött tojáshéjakban ülő figurák; ukrán zászló lengetése; rikító sárga és kék színkód.', 'Közmondásos metafora („MINT KÉT TOJÁS”); minimális magyarázat nélküli asszociatív identitás-összemosás.', 1, 'Proxy karaktergyilkosság & báb-narratíva');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2025_004', '2025-07-12', 'FIDESZ-TÁBOR', 'PROXY', 'Kormánypárti kampányfelület', 'vagott_kepek/HUN_PLAKAT_2025_004.jpg', '„Volt egy zápor”', 'A Tisza Párt kongresszusának helyszínén leparkolt teherautóra szerelt, Magyar Pétert gúnyoló plakát.', 'Mobil óriásplakát teherautón (504 x 238 cm)', 'Célzott helyszíni trollkampány, amely Magyar Péter viharral kapcsolatos nyilatkozatát figurázta ki.', 'Telex', 'https://telex.hu/belfold/2025/07/12/magyar-petert-gunyolo-plakat-varja-a-tiszasokat-a-kongresszus-helyszinen', 'NEGATIV_TAMADO', 'Gúnyos politikai delegitimálás; a Tisza Párt kongresszusi eseményének és vezetőjének nevetségessé tétele.', 'Mozgó teherautós gerilla-óriásplakát a Tisza kongresszus helyszínén; esőáztatta hangulat; minimalista betűtípus.', 'Eufemisztikus gúny és idézőjeles lekicsinylés („Volt egy zápor”); kontextuális politikai vicc a sajtóhírekre reagálva.', 1, 'Proxy karaktergyilkosság & báb-narratíva');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2025_005', '2025-10-04', 'FIDESZ-TÁBOR', 'STATE', 'Magyarország Kormánya (Miniszterelnöki Kabinetiroda)', 'vagott_kepek/HUN_PLAKAT_2025_005.jpg', '„Brüsszel bábjai adót akarnak emelni! – Nemzeti Konzultáció”', 'Bábozó kézmozdulatot tevő Ursula von der Leyen sötétkék háttér előtt.', 'Óriásplakát / Eurobillboard (504 x 238 cm, 12 m2)', 'Az őszi Nemzeti Konzultációt népszerűsítő állami hirdetés, brüsszeli adóemelési keretezéssel.', 'HVG', 'https://hvg.hu/itthon/20251004_Ursula-Von-der-Leyen-babozas-nemzeti-konzultacio-plakat-ebx', 'NEGATIV_TAMADO', 'Egzisztenciális fenyegetés (adóemelés); a brüsszeli vezetés és a hazai ellenzék báb-kapcsolatának vádkonstrukciója.', 'Metaforikus bábozó kéz a felső képtérben; zsinóron mozgatott ellenzéki politikusok; hideg kék-sárga EU színvilág.', 'Címkéző vádemelés és fenyegetéskeretezés („Brüsszel bábjai adót akarnak emelni!”); közvetlen anyagi fenyegetettség érzékeltetése.', 2, 'Állami szuverenitási & háborús diskurzus');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2025_006', '2025-10-04', 'FIDESZ-TÁBOR', 'STATE', 'Magyarország Kormánya (Miniszterelnöki Kabinetiroda)', 'vagott_kepek/HUN_PLAKAT_2025_006.jpg', '„A családi adócsökkentés az Ön családjának is jár!”', 'Mosolygó család közös étkezés közben, világos fotón.', 'Óriásplakát / Eurobillboard (504 x 238 cm, 12 m2)', 'A bábozós negatív konzultációs plakátokkal párhuzamosan futó pozitív állami imázskampány.', 'HVG', 'https://hvg.hu/itthon/20251004_Ursula-Von-der-Leyen-babozas-nemzeti-konzultacio-plakat-ebx', 'POZITIV_EPITO', 'Családpolitikai jóléti intézkedések; adócsökkentés népszerűsítése; szociális biztonságérzet erősítése.', 'Harmonikus, mosolygó többgenerációs család közös étkezése; meleg természetes fények; otthonos, polgári idill.', 'Megszólító jogosultsági ígéret („A családi adócsökkentés az Ön családjának is jár!”); inkluzív állami gondoskodás.', 2, 'Kormányzati szakpolitikai kommunikáció');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2025_007', '2025-12-04', 'FIDESZ-TÁBOR', 'PARTY', 'Hegyvidéki Fidesz-kampány (XII. kerület)', 'vagott_kepek/HUN_PLAKAT_2025_007.jpg', '„Ki az a Steiner Attila?”', 'Fekete-fehér stílusú, férfi sziluettet ábrázoló figyelemfelkeltő plakát a XII. kerületben.', 'Oszlopplakát / Citylight (B1: 70 x 100 cm)', 'Bevezető kampányplakát a fideszes jelölt, Steiner Attila ismertségének növelésére.', '444.hu', 'https://444.hu/2025/12/04/ki-az-a-steiner-attila-feliratu-plakatok-jelentek-meg-magyar-peter-valasztokeruleteben', 'TEASER_SEMLEGES', 'Új politikai szereplő (Steiner Attila államtitkár/képviselőjelölt) bevezetése a közvéleménybe; figyelemfelkeltés.', 'Magas kontrasztú fekete-fehér arculat; arc nélküli rejtélyes férfisziluett; tiszta, sallangmentes háttér.', 'Kíváncsiságkeltő retorikai kérdés („Ki az a Steiner Attila?”); teaser kampánystratégia, várakozáskeltés.', 0, 'Választási jelöltállítás & mozgósítás');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2026_008', '2026-02-04', 'FIDESZ-TÁBOR', 'STATE', 'Magyarország Kormánya (Miniszterelnöki Kabinetiroda)', 'vagott_kepek/HUN_PLAKAT_2026_008.jpg', '„Üzenjük Brüsszelnek: NEM FIZETÜNK! – Nemzeti Petíció”', 'Volodimir Zelenszkij, Ursula von der Leyen és Manfred Weber; jobb oldalon piros körben NEM FIZETÜNK!', 'Óriásplakát / Eurobillboard (504 x 238 cm, 12 m2)', 'Kampányidőszak előtti állami plakátkampány, fizetési kötelezettségként bemutatva az EU-támogatást.', 'Telex', 'https://telex.hu/belfold/2026/02/21/kampanyidoszak-ajanlasok-gyujtese-jeloles-legfontosabb-tudnivalok', 'NEGATIV_TAMADO', 'Pénzügyi szuverenitás és büntetések megtagadása; uniós elvárásokkal szembeni ellenállás (Nemzeti Petíció).', 'Ursula von der Leyen, Manfred Weber és Volodimir Zelenszkij arcképei nyomasztó háttérben; nagy méretű, vörös figyelmeztető tiltó sávok.', 'Kollektív dac imperatívusza és elutasító felkiáltás („Üzenjük Brüsszelnek: NEM FIZETÜNK!”); harcias ellenállási retorika.', 2, 'Állami szuverenitási & háborús diskurzus');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2026_009', '2026-02-04', 'FIDESZ-TÁBOR', 'PROXY', 'Nemzeti Ellenállás Mozgalom (Apáti Bence)', 'vagott_kepek/HUN_PLAKAT_2026_009.jpg', '„ADÓEMELÉST! / PÉNZT UKRAJNÁNAK! – IGENIS! – NEM TUD NEKIK NEMET MONDANI”', 'Parancsoló brüsszeli vezetők, előttük meghajolva IGENIS! felirattal válaszoló Magyar Péter.', 'Óriásplakát / Eurobillboard (504 x 238 cm, 12 m2)', 'Negatív plakátsorozat az óbudai Szentendrei úti plakátfalon.', '24.hu', 'https://24.hu/belfold/2026/04/17/obudai-plakatokkal-boritott-haz-vereseg-utan/', 'NEGATIV_TAMADO', 'Magyar Péter politikai akaratgyengeségének és brüsszeli alárendeltségének leleplezési kísérlete.', 'Karikatúra-jellegű megalázkodó beállítás; parancsoló kezek felülről; rikító piros és sárga figyelemfelkeltő feliratok.', 'Katonás parancs-engedelmesség struktúra („ADÓEMELÉST! PÉNZT UKRAJNÁNAK! – IGENIS!”) és sommás ítélet („NEM TUD NEKIK NEMET MONDANI”).', 1, 'Proxy karaktergyilkosság & báb-narratíva');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2026_010', '2026-02-24', 'FIDESZ-TÁBOR', 'PARTY', 'Fidesz – Magyar Polgári Szövetség – KDNP', 'vagott_kepek/HUN_PLAKAT_2026_010.jpg', '„A BIZTOS VÁLASZTÁS – Fidesz–KDNP (Berkó Attila)”', 'Fehér és narancssárga arculat, a jelölt portréja, alul narancssárga sávban: A BIZTOS VÁLASZTÁS.', 'Óriásplakát és Oszlopplakát (B1: 70 x 100 cm)', 'A Fidesz–KDNP hivatalos 2026-os pártkampányának stabilitást hangsúlyozó központi arculata.', 'Szolnok TV / Hírös.hu', 'https://www.szolnoktv.hu/hirek/egyre-tobb-a-valasztasi-plakat', 'POZITIV_EPITO', 'Kormányzati stabilitás és helyi képviselet; a hivatalos kormánypárti egyéni jelölt (Berkó Attila) legitimálása.', 'Narancs-fehér hivatalos Fidesz-KDNP arculat; öltönyös, professzionális, bizalmat keltő politikusportré közvetlen szemkontaktussal.', 'Minősítő tételmondat („A BIZTOS VÁLASZTÁS”); a kockázatkerülésre és a stabilitásra építő politikai toposz.', 0, 'Választási jelöltállítás & mozgósítás');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2026_011', '2026-04-08', 'FIDESZ-TÁBOR', 'STATE', 'Magyarország Kormánya (Miniszterelnöki Kabinetiroda)', 'vagott_kepek/HUN_PLAKAT_2026_011.jpg', '„Védett üzemanyagár – A benzin és a gázolaj hazánkban a legolcsóbb Európában!”', 'Kormányzati kék arculati hátteren üzemanyag-pisztoly és a védett ár eredményei.', 'Óriásplakát / Eurobillboard (504 x 238 cm, 12 m2)', 'Választás előtti állami plakátkampány, védőpajzsként bemutatva a kormányt az üzemanyagárakban.', 'Telex', 'https://telex.hu/gazdasag/2026/04/08/benzin-gazolaj-uzemanyag-tankolas-kampany-propaganda', 'POZITIV_EPITO', 'Rezsivédelem, megfizethető üzemanyagárak; a kormányzati gazdasági intézkedések nemzetközi felsőbbrendűsége.', 'Benzinkút piktogram, ábrázolt árösszehasonlítás, kék kormányzati alapszín, pozitív zöld megerősítő grafikai elemek.', 'Tényszerűséget sugalló szuperlatívusz („Védett üzemanyagár – ...legolcsóbb Európában!”); gazdasági sikerpropaganda.', 0, 'Kormányzati szakpolitikai kommunikáció');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2026_012', '2026-02-25', 'TISZA PÁRT', 'PARTY', 'TISZA – Tisztelet és Szabadság Párt', 'vagott_kepek/HUN_PLAKAT_2026_012.jpg', '„TISZA – VÁLASZTÁS 2026 (Mészáros Dávid)”', 'Kék-fehér-piros TISZA arculat, egyéni jelölt portréja, piros mezőben fehér betűkkel a név.', 'Kandeláberplakát, hullámpolitén tábla (B1: 70 x 100 cm)', 'Óriásplakát-bojkott miatti kandeláberes egyéni jelölti kampány.', 'Kanizsa Médiaház / Szolnok TV', 'https://kanizsamediahaz.hu/hir/202603/plakaterdo-mar-kanizsat-is-elleptek-a-valasztasi-plakatok', 'POZITIV_EPITO', 'Ellenzéki kihívó helyi szintű bemutatása; a Tisza Párt egyéni jelöltjének (Mészáros Dávid) ismertségépítése.', 'Kandeláberre rögzített kartonplakát; piros-fehér-kék nemzeti trikolór arculat; fiatal, civil benyomást keltő portré.', 'Funkcionális, azonosító márkázás („TISZA – VÁLASZTÁS 2026”); közvetlen jelölti megnevezés sallangok nélkül.', 0, 'Választási jelöltállítás & mozgósítás');
INSERT INTO plakatok (id, datum, politikai_tabor, kibocsato_tipus, hivatalos_kiado, fajl_nev, plakat_szlogen, vizualis_leiras, formatum_meret, politikai_elemzes, forras_nev, forras_url, kampany_tonus, tartalmi_fokusz, vizualis_szemiotika, szlogen_retorika, latens_tema_id, latens_tema_nev) VALUES ('HUN_PLAKAT_2026_013', '2026-03-01', 'TISZA PÁRT', 'GRASSROOTS', 'TISZA Párt (Szimpatizánsok otthonai)', 'vagott_kepek/HUN_PLAKAT_2026_013.jpg', '„Most vagy soha!”', 'Magánházak kerítésére, társasházi erkélyekre kihelyezett TISZA-molinók és plakátok.', 'Erkély-/kerítésmolinó (200 x 100 cm) és kertplakát', 'Az óriásplakát-piac ellensúlyozása szimpatizánsok saját ingatlanjainak hirdetőfelületté alakításával.', '444.hu / HVG', 'https://444.hu/2026/03/01/a-tiszasok-az-otthonaikra-erositett-plakatokkal-szallnak-be-a-kampanyba', 'POZITIV_EPITO', 'Rendszerváltó hangulat, állampolgári ellenállás és önkéntes mozgósítás; politikai fordulat sürgetése.', 'Magánház kerítésére/erkélyére rögzített lakossági molinó; DIY / grassroots esztétika; Tisza logó és nemzeti színek.', 'Petőfies, nemzeti-romantikus imperatívusz („Most vagy soha!”); végletes morális és történelmi döntéskényszer.', 0, 'Választási jelöltállítás & mozgósítás');
